//! Test support: a full-depth reference deposit tree, the Envio fixture, and
//! a fake Envio (`TickBuilder`) for model tests.
//!
//! `tests/fixtures/envio_tree_2100.json` is generated by
//! `tests/fixtures/gen_envio_tree.cjs` from the real Envio `DepositRecorded`
//! handler: 2100 deposits on chain index 0, their leaf hashes, and the root
//! Envio stored after each deposit.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use psy_bridge_reader_api::{DepositRow, FinalizedBatchRow, WithdrawalClaimRow};

use crate::model::{ApplyOutcome, ChainProgress, Cursors, DepositWithLeaf, Identity, Model, TickData, TreeMetaRow};
use crate::tree::hash::{parse_display_hex, two_to_one, zero, Hash};

const DEPTH: u8 = 32;

#[derive(Debug, Clone)]
pub struct EnvioTreeFixture {
    /// Leaf hash of deposit `i`, by chain-local deposit index.
    pub leaves: Vec<Hash>,
    /// `roots_after[k]` is Envio's display hex root after deposit `k`, that is
    /// the root at count `k + 1`.
    pub roots_after: Vec<String>,
}

/// The parsed Envio fixture. Panics if the file is missing or malformed.
pub fn fixture() -> EnvioTreeFixture {
    static FIXTURE: OnceLock<EnvioTreeFixture> = OnceLock::new();
    FIXTURE.get_or_init(load_fixture).clone()
}

fn load_fixture() -> EnvioTreeFixture {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/envio_tree_2100.json");
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path}: {e}"));
    let json: serde_json::Value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse {path}: {e}"));
    let strings = |field: &str| -> Vec<String> {
        json[field]
            .as_array()
            .unwrap_or_else(|| panic!("{path}: {field} is not an array"))
            .iter()
            .map(|v| v.as_str().unwrap_or_else(|| panic!("{path}: {field} has a non-string entry")).to_owned())
            .collect()
    };
    let leaves = strings("leaves")
        .iter()
        .map(|s| parse_display_hex(s).unwrap_or_else(|e| panic!("{path}: leaf: {e}")))
        .collect::<Vec<_>>();
    let roots_after = strings("roots_after");
    assert_eq!(leaves.len(), roots_after.len(), "{path}: one root per leaf");
    EnvioTreeFixture { leaves, roots_after }
}

/// Every level of the tree over `leaves[0..n)`, with zeros elsewhere. Level
/// `k` holds only the nodes that cover `[0, n)`; a node past the end is
/// `zero(k)`. Level 32 is the root alone, or empty when `n == 0`.
fn naive_levels(leaves: &[Hash], n: u64) -> Vec<Vec<Hash>> {
    let n = usize::try_from(n).expect("count fits usize");
    assert!(n <= leaves.len(), "count {n} exceeds the {} leaves given", leaves.len());
    let mut levels = vec![leaves[..n].to_vec()];
    for level in 0..DEPTH {
        let below = &levels[usize::from(level)];
        let above = below
            .chunks(2)
            .map(|pair| two_to_one(pair[0], pair.get(1).copied().unwrap_or_else(|| zero(level))))
            .collect();
        levels.push(above);
    }
    levels
}

/// Root of the depth-32 tree over `leaves[0..n)`; `zero(32)` when `n == 0`.
pub fn naive_root(leaves: &[Hash], n: u64) -> Hash {
    naive_levels(leaves, n)[usize::from(DEPTH)].first().copied().unwrap_or_else(|| zero(DEPTH))
}

/// The 32 siblings of leaf `i` in the tree over `leaves[0..n)`, level 0 first.
/// Requires `i < n`.
pub fn naive_siblings(leaves: &[Hash], i: u64, n: u64) -> Vec<Hash> {
    assert!(i < n, "leaf {i} is not below count {n}");
    let levels = naive_levels(leaves, n);
    (0..DEPTH)
        .map(|level| {
            let sibling = usize::try_from((i >> level) ^ 1).expect("index fits usize");
            levels[usize::from(level)].get(sibling).copied().unwrap_or_else(|| zero(level))
        })
        .collect()
}

/// A fake Envio for model tests: deposits per chain_index, claims and batches
/// per chain_id, and the progress and tree meta a tick reports. `tick` reads
/// from the model's cursors the way the PostgreSQL source does. Tests change
/// the public fields directly to simulate reorgs and bad rows.
pub struct TickBuilder {
    pub identity: Identity,
    pub started_unix_ms: u64,
    /// Keyed by chain_id.
    pub progress: BTreeMap<u64, ChainProgress>,
    /// Keyed by chain_index, in chain-local order.
    pub deposits: BTreeMap<u64, Vec<DepositWithLeaf>>,
    /// Keyed by chain_id, in `(block_number, id)` order.
    pub claims: BTreeMap<u64, Vec<WithdrawalClaimRow>>,
    /// Keyed by chain_id, in `(block_number, id)` order.
    pub batches: BTreeMap<u64, Vec<FinalizedBatchRow>>,
    /// Replaces the root a chain index's `DepositTreeMeta` reports.
    pub meta_root: BTreeMap<u64, Hash>,
    fixture_leaves: Vec<Hash>,
    next_deposit_index: u64,
}

impl Default for TickBuilder {
    fn default() -> Self {
        Self::new()
    }
}

impl TickBuilder {
    pub fn new() -> Self {
        TickBuilder {
            identity: Identity { chains_oid: 1, deposit_oid: 2 },
            started_unix_ms: 1_000,
            progress: BTreeMap::new(),
            deposits: BTreeMap::new(),
            claims: BTreeMap::new(),
            batches: BTreeMap::new(),
            meta_root: BTreeMap::new(),
            fixture_leaves: fixture().leaves,
            next_deposit_index: 0,
        }
    }

    pub fn progress(&mut self, chain_id: u64, progress_block: i64, max_reorg_depth: u64) -> &mut Self {
        self.progress.insert(chain_id, ChainProgress { chain_id, progress_block, max_reorg_depth });
        self
    }

    /// Leaf `local` of a chain index: the Envio fixture's on chain index 0,
    /// fresh two-to-one hashes of it elsewhere and past its end.
    pub fn leaf(&self, chain_index: u64, local: u64) -> Hash {
        let n = self.fixture_leaves.len() as u64;
        let base = self.fixture_leaves[(local % n) as usize];
        if chain_index == 0 && local < n { base } else { two_to_one(base, Hash::from_values(chain_index + 1, local, 0, 0)) }
    }

    /// Appends a deposit with the next global deposit_index.
    pub fn deposit(&mut self, chain_index: u64, chain_id: u64, block_number: u64, shield_address: &str) -> DepositRow {
        self.deposit_at(chain_index, chain_id, self.next_deposit_index, block_number, shield_address)
    }

    pub fn deposit_at(
        &mut self,
        chain_index: u64,
        chain_id: u64,
        deposit_index: u64,
        block_number: u64,
        shield_address: &str,
    ) -> DepositRow {
        self.next_deposit_index = self.next_deposit_index.max(deposit_index + 1);
        let local = self.deposits.get(&chain_index).map_or(0, |rows| rows.len() as u64);
        let leaf = self.leaf(chain_index, local);
        let row = DepositRow {
            id: format!("{chain_id}-{deposit_index}"),
            chain_id,
            chain_index,
            deposit_index,
            chain_local_deposit_index: local,
            shield_address: shield_address.to_owned(),
            token: "0xtoken".to_owned(),
            l2_token_contract_id: "7".to_owned(),
            amount: "100".to_owned(),
            note_commitment: format!("0xnote{chain_index}_{local}"),
            leaf_hash: format!("0xevent{chain_index}_{local}"),
            block_number,
            block_timestamp: block_number * 12,
            tx_hash: format!("0xtx{chain_index}_{local}"),
        };
        self.deposits.entry(chain_index).or_default().push(DepositWithLeaf {
            row: row.clone(),
            leaf,
            leaf_deposit_index: deposit_index,
            leaf_chain_id: chain_id,
            leaf_block_number: block_number,
        });
        row
    }

    pub fn rows(&self, chain_index: u64) -> Vec<DepositRow> {
        self.deposits.get(&chain_index).map_or_else(Vec::new, |rows| rows.iter().map(|r| r.row.clone()).collect())
    }

    pub fn leaves(&self, chain_index: u64) -> Vec<Hash> {
        self.deposits.get(&chain_index).map_or_else(Vec::new, |rows| rows.iter().map(|r| r.leaf).collect())
    }

    pub fn claim(&mut self, chain_id: u64, block_number: u64, nullifier: &str) -> WithdrawalClaimRow {
        let row = WithdrawalClaimRow {
            id: format!("{chain_id}-{nullifier}"),
            chain_id,
            nullifier: nullifier.to_owned(),
            recipient: "0xrecipient".to_owned(),
            token: "0xtoken".to_owned(),
            amount: "5".to_owned(),
            block_number,
            tx_hash: format!("0xclaim{nullifier}"),
        };
        let rows = self.claims.entry(chain_id).or_default();
        rows.push(row.clone());
        rows.sort_by(|a, b| (a.block_number, &a.id).cmp(&(b.block_number, &b.id)));
        row
    }

    pub fn batch(&mut self, chain_id: u64, block_number: u64, checkpoint_id: u64) -> FinalizedBatchRow {
        let row = FinalizedBatchRow {
            id: format!("{chain_id}-{checkpoint_id}"),
            chain_id,
            finalized_checkpoint_id: checkpoint_id.to_string(),
            deposit_tree_root: "0xdroot".to_owned(),
            withdrawal_tree_root: "0xwroot".to_owned(),
            block_number,
            tx_hash: format!("0xbatch{checkpoint_id}"),
        };
        let rows = self.batches.entry(chain_id).or_default();
        rows.push(row.clone());
        rows.sort_by(|a, b| (a.block_number, &a.id).cmp(&(b.block_number, &b.id)));
        row
    }

    pub fn tick(&self, cursors: &Cursors) -> TickData {
        self.tick_limited(cursors, usize::MAX)
    }

    /// A tick whose follow reads return at most `max_rows` rows each.
    pub fn tick_limited(&self, cursors: &Cursors, max_rows: usize) -> TickData {
        let mut truncated = false;
        fn limit<T>(rows: Vec<T>, max_rows: usize, truncated: &mut bool) -> Vec<T> {
            *truncated |= rows.len() > max_rows;
            rows.into_iter().take(max_rows).collect()
        }
        let mut deposits = BTreeMap::new();
        let mut metas = Vec::new();
        for (&chain_index, rows) in &self.deposits {
            let from = cursors.deposits.get(&chain_index).map_or(0, |c| c.local_count) as usize;
            deposits.insert(chain_index, limit(rows.get(from..).unwrap_or(&[]).to_vec(), max_rows, &mut truncated));
            let leaves = self.leaves(chain_index);
            let root = self.meta_root.get(&chain_index).copied().unwrap_or_else(|| naive_root(&leaves, leaves.len() as u64));
            metas.push(TreeMetaRow { chain_index, last_count: leaves.len() as u64, root });
        }
        let after = |cursor: Option<&(u64, String)>, block: u64, id: &str| cursor.is_none_or(|(b, i)| (block, id) > (*b, i.as_str()));
        let mut claims = BTreeMap::new();
        for (&chain_id, rows) in &self.claims {
            let cursor = cursors.claims.get(&chain_id);
            claims.insert(chain_id, limit(rows.iter().filter(|r| after(cursor, r.block_number, &r.id)).cloned().collect(), max_rows, &mut truncated));
        }
        let mut batches = BTreeMap::new();
        for (&chain_id, rows) in &self.batches {
            let cursor = cursors.batches.get(&chain_id);
            batches.insert(chain_id, limit(rows.iter().filter(|r| after(cursor, r.block_number, &r.id)).cloned().collect(), max_rows, &mut truncated));
        }
        TickData {
            identity: self.identity,
            started_unix_ms: self.started_unix_ms,
            progress: self.progress.values().copied().collect(),
            metas,
            deposits,
            claims,
            batches,
            truncated,
        }
    }

    /// Applies the next untruncated tick to `model`.
    pub fn apply_to(&self, model: &mut Model) -> ApplyOutcome {
        model.apply(self.tick(&model.cursors()))
    }
}
